css:
[data-bz-node="loc-store-band"]{padding-top:90px;padding-bottom:90px;}
[data-bz-node="loc-store-band"] .bz-block{padding-block:0;}
/* The handoff splits this 1.5fr / 1fr with a 48px gutter. */
[data-bz-node="loc-store-row"]{display:grid;grid-template-columns:1.5fr 1fr;gap:48px;align-items:start;}
.bz-block[data-bz-node="loc-store-heading"] p.bz-eyebrow{font:700 11px/1 var(--font-body);letter-spacing:.16em;color:var(--muted);margin:0 0 18px;}
[data-bz-node="loc-store-heading"] h2{font:800 30px/1.7 var(--font-heading);letter-spacing:normal;margin:0 0 18px;}
[data-bz-node="loc-store-address"]{margin-bottom:22px;}
[data-bz-node="loc-store-address"] .bz-text{max-width:none;}
[data-bz-node="loc-store-address"] p{font-size:16px;line-height:1.75;color:#3f3f3f;margin:0;}
[data-bz-node="loc-store-phones-row"]{display:flex;flex-direction:column;gap:8px;margin-bottom:22px;}
.ss-phone{display:flex;gap:12px;align-items:baseline;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:12px;font-size:16px;line-height:1.7;}
.ss-phone__label{font:700 10px/1.4 var(--font-body);letter-spacing:.12em;color:var(--muted);min-width:128px;}
.ss-phone__value{font:700 15px/1.7 var(--font-body);color:#242424;text-decoration:none;}
.ss-notice{background:#242424;padding:26px;}
.ss-notice__kicker{font:700 10px/1.3 var(--font-body);letter-spacing:.14em;color:var(--accent);margin-bottom:18px;}
.bz-block h3.ss-notice__title{font:800 20px/1.7 var(--font-heading);color:#fff;margin:0 0 12px;}
.bz-block p.ss-notice__body{font-size:15px;line-height:1.7;color:#C7C1B4;margin:15px 0 14px;}
.ss-notice__link{font:700 16px/1.7 var(--font-body);color:#fff;text-decoration:none;}
/* Framed map: fixed height so the two-up keeps its proportion. */
[data-bz-node="loc-store-map"]{height:520px;border:1px solid var(--line);background:var(--paper);overflow:hidden;}
[data-bz-node="loc-store-map"] .bz-container,[data-bz-node="loc-store-map"] figure{height:100%;}
[data-bz-node="loc-store-map"] img{width:100%;height:100%;object-fit:cover;display:block;}
@media (max-width:1100px){[data-bz-node="loc-store-row"]{grid-template-columns:1fr;gap:40px;}}
@media (max-width:640px){[data-bz-node="loc-store-map"]{height:320px;}[data-bz-node="loc-store-band"]{padding-top:56px;padding-bottom:56px;}}
